CREATE OR REPLACE FUNCTION public.set_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  new.updated_at = now();
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.mission_catalogue_origin_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
 if tg_op='DELETE' then
  if old.actionables_reference is not null and not public.fets_actionables_can_manage() then raise exception 'Management removes institutions from the supplied catalogue';end if;
  return old;
 end if;
 if tg_op='UPDATE' and new.actionables_reference is distinct from old.actionables_reference then raise exception 'Keep the supplied project reference intact; edit the working contact details instead';end if;
 if tg_op='INSERT' and new.actionables_reference is not null and auth.uid() is not null then raise exception 'Project reference imports require the reviewed migration';end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION public.mission_stage_completion_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
 if tg_op='UPDATE' and (new.id,new.institution_id,new.stage_key,new.created_at) is distinct from (old.id,old.institution_id,old.stage_key,old.created_at) then raise exception 'Stage origin cannot change';end if;
 if new.completed_at is not null then
  if length(btrim(new.completion_note))=0 then raise exception 'Record the stage result or evidence before completing it';end if;
  if exists(select 1 from public.mission_work_items where institution_stage_id=new.id and status<>'done') then raise exception 'Complete or reassign the open duties before completing this stage';end if;
  if new.stage_key='handover' and exists(select 1 from public.mission_work_items where institution_id=new.institution_id and status<>'done') then raise exception 'Complete all institution duties before recording delivery';end if;
  if new.stage_key='handover' and exists(select 1 from public.mission_institution_stages where institution_id=new.institution_id and position<new.position and completed_at is null) then raise exception 'Complete the earlier stages before recording delivery';end if;
  if tg_op='INSERT' or old.completed_at is null then new.completed_at:=now();select id into new.completed_by from public.staff_profiles where user_id=auth.uid() limit 1;else new.completed_at:=old.completed_at;new.completed_by:=old.completed_by;end if;
 else new.completed_by:=null;end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION public.mission_sync_task_result()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare task_id uuid; latest public.mission_task_updates;begin
 task_id:=case when tg_op='DELETE' then old.work_item_id else new.work_item_id end;
 perform 1 from public.mission_work_items where id=task_id for update;
 select * into latest from public.mission_task_updates where work_item_id=task_id order by created_at desc,id desc limit 1;
 update public.mission_work_items set status=coalesce(latest.status,'open'),blocker=case when latest.status='blocked' then latest.content else null end where id=task_id;
 -- New work or a changed outcome reopens a previously completed stage and delivery sign-off.
 update public.mission_institution_stages s set completed_at=null,completed_by=null
 where s.completed_at is not null and (s.id=(select institution_stage_id from public.mission_work_items where id=task_id and status<>'done') or (s.stage_key='handover' and s.institution_id=(select institution_id from public.mission_work_items where id=task_id and status<>'done')));
 if tg_op='DELETE' then return old;end if;return new;
end $function$

CREATE OR REPLACE FUNCTION public.mission_task_update_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
 if tg_op='UPDATE' and (new.id,new.work_item_id,new.author_id,new.created_at) is distinct from (old.id,old.work_item_id,old.author_id,old.created_at) then raise exception 'Result origin cannot change';end if;
 if tg_op='INSERT' then new.created_at:=clock_timestamp();select id into new.author_id from public.staff_profiles where user_id=auth.uid() limit 1;select report_to_id,report_instructions into new.report_to_id,new.report_method from public.mission_work_items where id=new.work_item_id;
 else new.report_to_id:=old.report_to_id;new.report_method:=old.report_method;end if;
 if new.follow_up_at is not null then new.follow_up_date:=(new.follow_up_at at time zone 'Asia/Kolkata')::date;end if;
 select id into new.edited_by from public.staff_profiles where user_id=auth.uid() limit 1;new.updated_at:=now();return new;
end $function$

CREATE OR REPLACE FUNCTION public.mission_reference_task_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
 if tg_op='UPDATE' and new.institution_id is distinct from old.institution_id and exists(select 1 from public.expansion_institutions where id=old.institution_id and actionables_reference is not null) then raise exception 'Project work stays with its institution';end if;
 if new.institution_id is not null and not exists(select 1 from public.expansion_institutions where id=new.institution_id) then raise exception 'Open an accessible institution before assigning work';end if;
 if exists(select 1 from public.expansion_institutions where id=new.institution_id and actionables_reference is not null) then
  if new.owner_id is not null and not exists(select 1 from fets_actionables_private.directory() d where d.id=new.owner_id and d.is_active) then raise exception 'Choose an approved project colleague to own this duty';end if;
  if new.report_to_id is not null and not exists(select 1 from fets_actionables_private.directory() d where d.user_id=new.report_to_id and d.is_active) then raise exception 'Choose an approved project colleague to receive the result';end if;
 end if;
 if tg_op='UPDATE' and new.reference_task_key is distinct from old.reference_task_key then raise exception 'A linked project task keeps its source identity';end if;
 if new.reference_task_key is not null and not exists(select 1 from public.expansion_institutions where id=new.institution_id and actionables_reference->>'id'=case new.reference_task_key when 1 then 'cochin-rajagiri' when 2 then 'thrissur-vidya' when 3 then 'kottayam-saintgits' when 4 then 'calicut-gec' when 5 then 'thrissur-sahrdaya' end) then raise exception 'Link the project task to its recorded institution';end if;
 if tg_op='INSERT' and new.reference_task_key is not null then
  if new.reference_task_key=3 then raise exception 'This project task is already recorded complete; add a separate follow-up if needed';end if;
  new.status:=case when new.reference_task_key in (2,5) then 'in_progress' else 'open' end;
 end if;
 new.source_team:=case new.reference_task_key when 1 then 'Scout Squad' when 2 then 'Tech Audit Squad' when 3 then 'Pearson Liaison' when 4 then 'Tech Audit Squad' when 5 then 'Operations Lead' else null end;
 return new;
end $function$

CREATE OR REPLACE FUNCTION public.mission_simple_task_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
 if tg_op='UPDATE' and (new.id,new.created_by,new.created_at) is distinct from (old.id,old.created_by,old.created_at) then raise exception 'Task origin cannot change';end if;
 if new.institution_stage_id is not null and not exists(select 1 from public.mission_institution_stages where id=new.institution_stage_id and institution_id=new.institution_id) then raise exception 'Choose a stage in this institution';end if;
 if new.owner_id is not null and (tg_op='INSERT' or new.owner_id is distinct from old.owner_id) and not exists(select 1 from public.staff_profiles where id=new.owner_id and is_active) then raise exception 'Assign an active staff member';end if;
 if new.report_to_id is not null and (tg_op='INSERT' or new.report_to_id is distinct from old.report_to_id) and not exists(select 1 from public.staff_profiles where user_id=new.report_to_id and is_active) then raise exception 'Choose an active staff member to receive the result';end if;
 if new.due_at is not null then new.due_date:=(new.due_at at time zone 'Asia/Kolkata')::date;end if;
 new.updated_at:=now();new.updated_by:=auth.uid();
 return new;
end $function$

CREATE OR REPLACE FUNCTION public.roster_timing_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
 if TG_OP='UPDATE' then
  new.version:=old.version+1;
  -- Older clients changing a code cannot leave the former shift's hours behind.
  if current_user in ('authenticated','anon') and new.shift_code is distinct from old.shift_code and new.shift_start is not distinct from old.shift_start and new.shift_end is not distinct from old.shift_end and new.shift_label is not distinct from old.shift_label then
   new.shift_start:=null;new.shift_end:=null;new.shift_label:=null;new.grace_minutes:=0;
  end if;
 else new.version:=1; end if;
 if upper(new.shift_code) not in ('D','E','HD','OT') then new.shift_start:=null;new.shift_end:=null;new.shift_label:=null;new.grace_minutes:=0;end if;
 new.updated_at:=clock_timestamp();
 return new;
end $function$

CREATE OR REPLACE FUNCTION public.notify_shift_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  staff_name TEXT;
  staff_branch TEXT;
  old_shift TEXT;
  new_shift TEXT;
  is_leave_or_ot BOOLEAN;
BEGIN
  -- Only notify on shift_code change
  IF OLD.shift_code = NEW.shift_code THEN
    RETURN NEW;
  END IF;

  old_shift := COALESCE(OLD.shift_code, 'None');
  new_shift := COALESCE(NEW.shift_code, 'None');

  -- STRICT FILTER: ONLY notify for leave and OT related changes
  is_leave_or_ot := FALSE;

  -- Leave codes: CL (Casual Leave), SL (Sick Leave), EL (Earned Leave), PLV (Privilege Leave), AL (Annual Leave), Absent
  IF old_shift IN ('CL', 'SL', 'EL', 'PLV', 'AL', 'absent', 'Absent', 'LOP', 'WFH') OR 
     new_shift IN ('CL', 'SL', 'EL', 'PLV', 'AL', 'absent', 'Absent', 'LOP', 'WFH') THEN
    is_leave_or_ot := TRUE;
  END IF;

  -- OT/Overtime check: only if overtime_hours changed or if it's explicitly OT
  IF (OLD.overtime_hours IS DISTINCT FROM NEW.overtime_hours AND NEW.overtime_hours > 0) OR
     old_shift = 'OT' OR new_shift = 'OT' THEN
    is_leave_or_ot := TRUE;
  END IF;

  -- If it's NOT a leave or OT change, skip notification completely
  IF NOT is_leave_or_ot THEN
    RETURN NEW;
  END IF;

  -- Get staff info
  SELECT full_name, branch_assigned INTO staff_name, staff_branch
  FROM staff_profiles
  WHERE id = NEW.profile_id;

  -- Create notification only for leave/OT changes
  INSERT INTO notifications (
    recipient_id,
    type,
    title,
    message,
    link,
    priority,
    metadata,
    branch_location
  ) VALUES (
    NEW.profile_id,
    'shift_changed',
    CASE 
      WHEN NEW.overtime_hours > 0 THEN 'Overtime Updated'
      WHEN new_shift IN ('CL', 'SL', 'EL', 'PLV', 'AL', 'LOP', 'WFH', 'absent', 'Absent') THEN 'Leave Updated'
      ELSE 'Roster Update'
    END,
    CASE
      WHEN NEW.overtime_hours > 0 THEN 'OT on ' || TO_CHAR(NEW.date, 'DD Mon') || ': ' || NEW.overtime_hours || ' hrs'
      ELSE 'Leave on ' || TO_CHAR(NEW.date, 'DD Mon') || ': ' || new_shift
    END,
    'fets-roster',
    'low',  -- Keep it low priority - informational only
    jsonb_build_object(
      'schedule_id', NEW.id,
      'date', NEW.date,
      'old_shift', old_shift,
      'new_shift', new_shift,
      'overtime_hours', NEW.overtime_hours
    ),
    staff_branch
  );

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION desk_workspace_private.application_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
 if current_user in ('authenticated','anon') and
  (new.workflow_version<>0 or (TG_OP='UPDATE' and old.workflow_version<>0)) then
  raise exception 'Use the current My Desk request form' using errcode='42501';
 end if;
 if TG_OP='UPDATE' then new.version:=old.version+1;end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION public.attendance_roster_status()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare r public.roster_schedules;
begin
 if new.check_in is not null and new.status in ('present','late') then
  select * into r from public.roster_schedules where profile_id=new.staff_id and date=new.date;
  if r.shift_start is null and r.shift_end is null and r.shift_code in ('D','OT') then r.shift_start:='08:00';r.shift_end:='17:00';end if;
  new.status:=case when r.shift_code in ('D','E','HD','OT') and r.shift_start is not null and new.check_in>r.shift_start+make_interval(mins=>r.grace_minutes) then 'late' else 'present' end;
 end if;
 return new;
end $function$

